CREATE OR REPLACE FUNCTION public.portfolio_pipeline(_workspace uuid) RETURNS TABLE(request_id uuid,project_id uuid,project_title text,builder_id uuid,builder_name text,pitch_sentence text,status text,created_at timestamptz,response_hours double precision) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.workspace_access(_workspace) THEN RAISE EXCEPTION 'Workspace membership required' USING ERRCODE='42501'; END IF; RETURN QUERY SELECT r.id,p.id,p.title,r.applicant_id,b.full_name,r.pitch_sentence,r.status::text,r.created_at,CASE WHEN r.responded_at IS NOT NULL THEN extract(epoch FROM(r.responded_at-r.created_at))::double precision/3600 END FROM workspace_projects wp JOIN projects p ON p.id=wp.project_id JOIN connect_requests r ON r.project_id=p.id JOIN profiles b ON b.id=r.applicant_id WHERE wp.workspace_id=_workspace AND NOT r.flagged; END $$;
CREATE OR REPLACE FUNCTION public.issue_verified_credential(_source text,_event text,_claim public.credential_claim) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE e credential_verified_events; cid uuid; BEGIN SELECT * INTO e FROM credential_verified_events WHERE source=_source AND event_id=_event; IF e.user_id IS NULL OR EXISTS(SELECT 1 FROM profiles WHERE id=e.user_id AND is_demo) THEN RAISE EXCEPTION 'Verified real event required'; END IF; IF _claim='Successful_Exit' THEN RAISE EXCEPTION 'Payment alone does not verify an exit'; END IF; IF _claim='Top_1_Percent_Committer' THEN RAISE EXCEPTION 'Population percentile verification is required'; END IF; IF _source<>'github' OR _claim<>'AI_Ship_Streak' OR coalesce((e.payload->>'verified_ai_release_days')::int,0)<7 THEN RAISE EXCEPTION 'Verified seven-day AI release streak required'; END IF; INSERT INTO builder_verifiable_credentials(user_id,claim_type,proof_hash,source,event_id) VALUES(e.user_id,_claim,encode(digest(jsonb_build_object('source',e.source,'event_id',e.event_id,'subject',e.user_id,'claim',_claim,'payload',e.payload)::text,'sha256'),'hex'),_source,_event) ON CONFLICT DO NOTHING RETURNING id INTO cid; RETURN cid; END $$;